# enumerate candidate 2x2 chunks containing 3 or 4 occupied and exact cover test
occ={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
cands=[]
for r in range(6):
 for c in range(6):
  cells={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  hit=cells&occ
  if len(hit) in (3,4): cands.append((r,c,hit,4-len(hit)))
sol=[]
def back(remaining, chosen):
 if not remaining:
  sol.append(chosen); return
 x=min(remaining)
 for cand in cands:
  if x in cand[2] and cand[2] <= remaining:
   back(remaining-cand[2], chosen+[cand])
back(occ,[])
len(sol), [[(x[0],x[1],len(x[2])) for x in s] for s in sol[:20]]
